"""Research-only donor acquisition and conservative structural census; never runtime."""
from __future__ import annotations
import argparse, ast, collections, datetime, hashlib, json, pathlib, re, subprocess
from concurrent.futures import ThreadPoolExecutor

ROOT = pathlib.Path(__file__).resolve().parents[2]
YN = ROOT / 'research/commerce'
SEEDS = ['mrkooblu/semrush-mcp', 'purahmanian/keepa-mcp',
 'purahmanian/junglescout-mcp', 'purahmanian/google-trends-mcp',
 'amzscout-corp/amzscout-skill-mcp', 'coaxon/amazon-mcp',
 'aws-samples/sample-amazon-spapi-mcp-server', 'microsoft/playwright-mcp',
 'firecrawl/firecrawl-mcp-server', 'apify/apify-mcp-server']
LANG = {'.py':'python','.js':'javascript','.mjs':'javascript','.cjs':'javascript','.jsx':'javascript','.ts':'typescript',
 '.tsx':'tsx','.rs':'rust','.go':'go','.java':'java','.cs':'csharp',
 '.sh':'bash','.c':'c','.h':'c','.cpp':'cpp','.rb':'ruby','.php':'php','.css':'css','.html':'html','.scss':'scss',
 '.mts':'typescript','.pyi':'python','.ex':'elixir','.exs':'elixir','.jsm':'javascript','.bash':'bash',
 '.ps1':'powershell','.m':'objc','.graphql':'graphql','.sql':'sql',
 '.vue':'vue','.astro':'astro','.fish':'fish','.pch':'objc','.ipynb':'python','.pyx':'cython','.pxd':'cython'}
# A failed primary grammar may be retried only with a grammar that accepts a superset of the
# file's language (SCSS ⊇ CSS, TSX ⊇ JSX) or one of the languages a .h header can legally hold.
# Template grammars (Twig, ...) are never fallbacks: they accept nearly any text, so a clean parse proves nothing.
FALLBACK = {'.css':['scss'],'.jsx':['tsx'],'.h':['cpp','objc']}
MANIFESTS = {'package.json','package-lock.json','pnpm-lock.yaml','yarn.lock',
 'Cargo.toml','Cargo.lock','pyproject.toml','poetry.lock','uv.lock','requirements.txt',
 'go.mod','go.sum','pom.xml','build.gradle','Dockerfile','Makefile'}
FACETS = {'network-behavior':r'https?://|fetch\(|requests\.|httpx|axios',
 'auth':r'(?i)authorization|api_key|apikey|access_token|oauth|bearer',
 'rate-limits':r'(?i)rate.?limit|quota|429|throttl',
 'errors':r'(?i)raise |throw |except |catch\s*\(|isError',
 'retry-semantics':r'(?i)retry|backoff|retries',
 'pagination':r'(?i)pagination|next.?token|cursor|page_size|offset',
 'storage':r'(?i)sqlite|redis|localStorage|writeFile|open\(',
 'process-model':r'(?i)subprocess|spawn\(|exec\(|stdio|StdioServerTransport',
 'protocols':r'(?i)StreamableHTTP|SSEServerTransport|FastMCP|McpServer|jsonrpc'}
def safe_excerpt(line):
 # Only this bounded prefix can be published; avoid rescanning multi-megabyte benchmark lines.
 line=line[:800]
 for pattern in [r"https://hooks\.slack\.com/services/[^\s\"'<>\\)]+",r'AKIA[0-9A-Z]{16}',r'(?<![A-Za-z0-9])gh[pousr]_[A-Za-z0-9]{25,}',r'(?<![A-Za-z0-9])sk-(?:proj-)?[A-Za-z0-9_-]{25,}',r'-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----']:
  line=re.sub(pattern,'[REDACTED_CREDENTIAL_LIKE_LITERAL]',line)
 return line[:400]

def now(): return datetime.datetime.now(datetime.timezone.utc).isoformat()
def git(*args, cwd=None, timeout=300):
 p = subprocess.run(['git','-c','core.longpaths=true','-c','http.version=HTTP/1.1',*args],cwd=cwd,capture_output=True,timeout=timeout)
 if p.returncode: raise RuntimeError(p.stderr.decode('utf-8','replace')[-3000:])
 return p.stdout.decode('utf-8','replace').strip()
def dump(path, value):
 path.parent.mkdir(parents=True,exist_ok=True)
 path.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def jsonl(path, rows):
 path.write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in rows),encoding='utf-8')

def classify(path, data):
 parts = path.lower().split('/'); name = parts[-1]; suffix = pathlib.Path(name).suffix
 # Pinned benchmark runners persist these as outputs, not executable/config source.
 if 'benchmarks' in parts and any(part in {'experiments','results'} for part in parts) and suffix=='.json': return 'FIXTURE'
 if re.search(rb'(?i)code generated[^\n]*do not edit',data[:2048]): return 'GENERATED'
 if re.search(rb'Generated by (Cython|SWIG) \d',data[:400]): return 'GENERATED'
 if any(p in {'vendor','vendored','node_modules','third_party','third-party'} for p in parts): return 'VENDORED'
 if any(p in {'dist','generated','__generated__'} for p in parts) or name.endswith(('.min.js','.map')): return 'GENERATED'
 if b'\0' in data: return 'BINARY'
 if any(p in {'fixtures','fixture','__fixtures__','snapshots','__snapshots__'} for p in parts): return 'FIXTURE'
 if name.startswith(('test_','test.')) or '.test.' in name or '.spec.' in name or name.endswith('_test.go') or any(p in {'test','tests','__tests__'} for p in parts): return 'TEST'
 if name in {x.lower() for x in MANIFESTS} or name.startswith(('docker-compose','requirements','dockerfile')) or '.github' in parts or '.husky' in parts: return 'BUILD'
 if suffix in LANG: return 'FIRST_PARTY_SOURCE'
 if data.startswith(b'#!') or name.endswith(('_bash_completion','_zsh_completion')): return 'FIRST_PARTY_SOURCE'
 if suffix in {'.pxd','.pyx','.idl','.pch','.fish'}: return 'FIRST_PARTY_SOURCE'
 if name in {'gemfile','rakefile','vagrantfile','pkgbuild','portfile','gradlew'}: return 'BUILD'
 if suffix in {'.gemspec','.kts','.nuspec','.mn','.pbxproj','.xcscheme','.vcxproj','.filters','.user','.diff','.bat','.tpl','.jinja2'}: return 'BUILD'
 if name in {'cname','version','build_number','expected_builds','procfile'} or suffix in {'.dist','.pro','.webmanifest','.types'}: return 'CONFIG'
 if name in {'authors','news'} or suffix in {'.license','.cff'}: return 'DOC'
 if suffix in {'.excalidraw','.xib','.rtf','.jp2'}: return 'ASSET'
 if 'schema' in name and suffix in {'.json','.yaml','.yml'}: return 'SCHEMA'
 if suffix in {'.md','.mdx','.rst','.txt','.toc','.todo','.1'} or name.startswith(('license','copying','notice')): return 'DOC'
 if suffix in {'.mustache','.tmpl','.csproj','.sln','.build','.xcconfig','.gradle'}: return 'BUILD'
 if suffix in {'.list','.jsonc','.typed','.properties','.http','.example'}: return 'CONFIG'
 if suffix in {'.po','.pot','.csv','.tsv','.pem','.crt'}: return 'ASSET'
 if suffix in {'.astro','.ipynb','.ps1','.m','.graphql'}: return 'FIRST_PARTY_SOURCE'
 if suffix in {'.json','.toml','.yaml','.yml','.ini','.cfg','.conf','.plist','.service','.in','.xml','.lock'} or name.startswith('.') or name.endswith(('rc','ignore')): return 'CONFIG'
 if suffix=='.patch': return 'BUILD'
 if suffix in {'.png','.jpg','.jpeg','.gif','.svg','.ico','.webp','.pdf','.woff','.woff2','.mp4','.zip'}: return 'ASSET'
 if suffix in {'.css','.scss','.html','.svelte','.vue','.sql'}: return 'FIRST_PARTY_SOURCE'
 return 'UNKNOWN'

def source_language(path, content):
 language=LANG.get(pathlib.Path(path).suffix)
 if language is None:
  first=content.split(b'\n',1)[0].decode('utf-8','replace')
  if first.startswith('#!'):
   if re.search(r'\bpython[0-9.]*\b',first):language='python'
   elif re.search(r'\b(?:bash|sh|zsh)\b',first):language='bash'
  if path.endswith(('_bash_completion','_zsh_completion')):language='bash'
 return language

def notebook_code(content):
 """Concatenated code cells of a Python notebook; IPython magics and shell escapes are blanked
 line for line so reported rows stay aligned. None when the notebook is not a Python notebook."""
 nb=json.loads(content)
 meta=nb.get('metadata',{}); kernel=(meta.get('kernelspec',{}).get('language') or meta.get('language_info',{}).get('name') or 'python').lower()
 if kernel!='python': return None
 cells=[]
 for c in nb.get('cells',[]):
  if c.get('cell_type')!='code': continue
  src=''.join(c['source']) if isinstance(c['source'],list) else c['source']
  cells.append('\n'.join('' if re.match(r'\s*[%!]',ln) else ln for ln in src.split('\n')))
 return '\n\n'.join(cells).encode()

def first_error(tree, content):
 def find(n):
  if n.type=='ERROR' or n.is_missing: return n
  for ch in n.children:
   if ch.has_error or ch.is_missing:
    r=find(ch)
    if r: return r
 node=find(tree.root_node); spans=[]
 def collect(n):
  if n.type=='ERROR' or n.is_missing: spans.append(max(1,n.end_byte-n.start_byte)); return
  for ch in n.children:
   if ch.has_error or ch.is_missing: collect(ch)
 collect(tree.root_node)
 return {'line':node.start_point.row+1 if node else None,'error_byte_ratio':round(min(1.0,sum(spans)/max(1,len(content))),4)}

def failure_reason(path, content, language):
 """A reason code for a source file no admissible grammar parses cleanly; heuristics only label
 the failure, they never turn it into a parse."""
 text=content.decode('utf-8','replace'); suffix=pathlib.Path(path).suffix
 if language is None: return 'NO_GRAMMAR_FOR_LANGUAGE'
 if re.search(r'Generated by (Cython|SWIG|protoc)',text[:400]): return 'GENERATED_SOURCE'
 if suffix in {'.c','.cpp','.h'} and re.search(r'^\s*(NS_IMPL_\w+|[A-Z_]{3,}\()|\b(CALLBACK|WINAPI|_In_|_In_opt_|APIENTRY)\b',text,re.M): return 'PREPROCESSOR_MACRO_EXPANSION_REQUIRED'
 if suffix=='.html' and re.search(r'\{%|\{\{',text): return 'TEMPLATE_LANGUAGE_IN_HOST_HTML'
 if suffix=='.cs' and '[CONTENT]' in text: return 'TEMPLATE_PLACEHOLDER_SOURCE'
 if suffix=='.sql': return 'SQL_DIALECT_OUTSIDE_GRAMMAR'
 if suffix=='.scss' and re.search(r'^@(use|forward)\b',text,re.M): return 'SCSS_MODULE_SYSTEM_OUTSIDE_GRAMMAR'
 if suffix=='.css' and re.search(r'^@(plugin|tailwind|apply|theme|custom-variant)\b|@import\s+"tailwindcss"',text,re.M): return 'CSS_FRAMEWORK_AT_RULE'
 if suffix in {'.ts','.tsx'} and re.search(r'export type \*|^\s*(abstract|accessor|satisfies)\??:|import\("[^"]+"\)\.',text,re.M): return 'TYPESCRIPT_SYNTAX_NEWER_THAN_GRAMMAR'
 return 'GRAMMAR_REJECTS_CONSTRUCT'

def parse_review(path, content, donor_tree=None):
 """Structural parse with the admissible grammars for a file, and a reason when none is clean."""
 language=source_language(path,content); suffix=pathlib.Path(path).suffix
 out={'status':'PARSE_UNKNOWN','language':language,'grammar':None,'method':None,'reason_code':None,'error':None,'symbols':[],'imports':[]}
 if language is None:
  out['reason_code']='NO_GRAMMAR_FOR_LANGUAGE'; return out
 try:
  from tree_sitter_language_pack import get_parser
 except Exception as e:
  out['reason_code']='PARSER_PACK_UNAVAILABLE'; out['imports']=[{'parse_error':str(e)}]; return out
 if language=='cython':
  # No tree-sitter grammar exists for Cython; Cython's own parser is the authoritative one.
  try:
   from Cython.Compiler import Errors
   from Cython.Compiler.TreeFragment import parse_from_strings
  except Exception as e:
   out['reason_code']='PARSER_PACK_UNAVAILABLE'; out['imports']=[{'parse_error':str(e)}]; return out
  Errors.init_thread()
  try: parse_from_strings(pathlib.Path(path).stem,content.decode('utf-8'))
  except (Errors.CompileError,UnicodeDecodeError): out['reason_code']='GRAMMAR_REJECTS_CONSTRUCT'; return out
  out.update(status='PARSED',grammar='cython',method='CYTHON_COMPILER_PARSER')
  return out
 body=content; method='PRIMARY_GRAMMAR'
 if suffix=='.ipynb':
  try: body=notebook_code(content)
  except Exception: out['reason_code']='NOTEBOOK_JSON_INVALID'; return out
  if body is None: out['reason_code']='NOTEBOOK_KERNEL_NOT_PYTHON'; return out
  method='NOTEBOOK_CODE_CELLS_MAGICS_BLANKED'
 for i,grammar in enumerate([language]+FALLBACK.get(suffix,[])):
  try: tree=get_parser(grammar).parse(body)
  except Exception as e:
   out['imports']=[{'parse_error':str(e)}]; out['reason_code']='NO_GRAMMAR_IN_PINNED_PARSER_PACK'; continue
  if i==0: out['error']=first_error(tree,body) if tree.root_node.has_error else None
  if tree.root_node.has_error: continue
  symbols=[]; imports=[]
  def walk(node):
   if node.type in {'function_definition','function_declaration','method_definition','class_definition','class_declaration','function_item','struct_item','interface_declaration','type_alias_declaration','enum_declaration'}:
    n=node.child_by_field_name('name')
    if n: symbols.append({'source_path':path,'symbol':n.text.decode('utf-8','replace'),'kind':node.type,'line_start':node.start_point.row+1,'line_end':node.end_point.row+1})
   if node.type in {'import_statement','import_from_statement','use_declaration','import_declaration','import_spec'}:
    imports.append({'source_path':path,'line':node.start_point.row+1,'text':node.text.decode('utf-8','replace')})
   for c in node.children: walk(c)
  walk(tree.root_node)
  out.update(status='PARSED',grammar=grammar,method=method if i==0 else 'SUPERSET_OR_HEADER_GRAMMAR_FALLBACK',reason_code=None,error=None,symbols=symbols,imports=imports)
  return out
 reference=reference_parse(path,content,language,donor_tree)
 if reference:
  out.update(status='PARSED',grammar=reference[0],method=reference[1],reason_code=None,error=None)
  return out
 if out['reason_code']!='NO_GRAMMAR_IN_PINNED_PARSER_PACK' or out['error']: out['reason_code']=failure_reason(path,content,language)
 invalid=confirm_invalid(path,content,language)
 if invalid:
  out.update(status='PARSE_INVALID_CONFIRMED',grammar=invalid[0],method='REFERENCE_PARSER_REJECTS',reason_code='INVALID_IN_DONOR',error=invalid[1])
 return out

TEMPLATE_TAG = re.compile(r'\{%.*?%\}|\{\{.*?\}\}|\{#.*?#\}', re.S)

def reference_parse(path, content, language, donor_tree=None):
 """When the tree-sitter grammar rejects a file, the language's own reference parser may still
 accept it: graphql-core (port of graphql-js) for GraphQL; for a Jinja template, Jinja's parser
 for the template layer AND the HTML grammar on the text with every template tag blanked (a
 template parser alone accepts nearly any text, so it never decides on its own)."""
 text=content.decode('utf-8','replace')
 if language=='graphql':
  try:
   import graphql
   graphql.parse(text)
   return ('graphql-core','GRAPHQL_REFERENCE_PARSER')
  except Exception: return None
 if language=='html' and TEMPLATE_TAG.search(text):
  try:
   import jinja2
   from tree_sitter_language_pack import get_parser
   jinja2.Environment().parse(text)
  except Exception: return None
  # A tag standing for an unquoted attribute value (attr={{ x }}) becomes a placeholder value of
  # the same length; every other tag becomes spaces. Literal ampersands are written out (the same
  # document under WHATWG).
  def blank(m):
   if re.search(r'=\s*$',text[max(0,m.start()-3):m.start()]) and '\n' not in m.group(0): return 'x'*len(m.group(0))
   return re.sub(r'[^\n]',' ',m.group(0))
  blanked=literal_ampersands(TEMPLATE_TAG.sub(blank,text))
  if get_parser('html').parse(blanked.encode()).root_node.has_error: return None
  return ('jinja2+html','JINJA_TEMPLATE_AND_HTML_WITH_TAGS_BLANKED')
 if language=='html' and not TEMPLATE_TAG.search(text):
  # WHATWG parsing (html5lib strict: any parse error rejects). html5lib predates the rule that an
  # ampersand starting no character reference is a literal "&", so such ampersands are written as
  # "&amp;" first: the same document under the current algorithm.
  try:
   import html5lib
   parser=html5lib.HTMLParser(strict=True)
   body=literal_ampersands(text)
   if re.match(r'\s*(<!--.*?-->\s*)*<(!doctype|html)\b',text,re.I|re.S): parser.parse(body)
   else:
    first=re.search(r'<([a-zA-Z][a-zA-Z0-9]*)',text)
    parser.parseFragment(body,container={'tr':'tbody','td':'tr','th':'tr','li':'ul','option':'select','tbody':'table','thead':'table'}.get(first.group(1).lower() if first else '','div'))
   return ('html5lib '+html5lib.__version__+' strict','WHATWG_PARSER_LITERAL_AMPERSANDS_NORMALISED')
  except Exception: return None
 if language=='scss' and donor_tree:
  return sass_compile(path,donor_tree)
 if language=='css':
  # CSS Syntax Module Level 3 (tinycss2): the browser parsing algorithm. Framework at-rules and
  # keyframe selector lists are valid syntax there; any parse-error node rejects the file.
  try:
   import tinycss2
   if not css_errors(tinycss2.parse_stylesheet(text,skip_comments=True,skip_whitespace=True)):
    return ('tinycss2','CSS_SYNTAX_LEVEL_3_REFERENCE_PARSER')
  except Exception: return None
  return None
 if language=='sql':
  return sql_parse(text)
 if pathlib.Path(path).suffix in ('.jsx','.ts','.tsx','.mts','.cts'):
  diagnostics=typescript_diagnostics(path,text)
  if diagnostics==[]: return ('typescript','TYPESCRIPT_COMPILER_SYNTAX')
 return None

def sass_compile(path, tree):
 """dart-sass, the reference Sass implementation pinned in tools/commerce/package-lock.json,
 compiles the file inside the donor's own stylesheet tree at the census commit (every .scss, .sass
 and .css blob extracted with git archive, so @use and @import resolve as the donor resolves
 them). A clean compile parses every rule of the file; nothing of the donor is executed."""
 import shutil,tempfile
 checkout,commit=tree
 sass=pathlib.Path(__file__).resolve().parent/'node_modules/.bin/sass'
 if not sass.is_file(): return None
 with tempfile.TemporaryDirectory() as root:
  names=[n for n in subprocess.run(['git','ls-tree','-r','-z','--name-only',commit],cwd=checkout,capture_output=True).stdout.decode().split('\0') if n.endswith(('.scss','.sass','.css'))]
  if path not in names: return None
  archive=subprocess.run(['git','archive',commit,'--']+names,cwd=checkout,capture_output=True)
  if archive.returncode!=0: return None
  subprocess.run(['tar','-x','-C',root],input=archive.stdout,check=True)
  target=pathlib.Path(root)/path
  if not target.is_file(): return None
  r=subprocess.run([str(sass),'--no-source-map','--quiet','--load-path',str(target.parent),'--load-path',root,str(target)],capture_output=True,timeout=120)
  if r.returncode!=0: return None
  version=subprocess.run([str(sass),'--version'],capture_output=True,text=True).stdout.split()[0]
  return ('dart-sass '+version,'DART_SASS_COMPILE_IN_DONOR_TREE')

def literal_ampersands(text):
 """Writes every "&" that starts no character reference as "&amp;" (WHATWG: such an ampersand is a
 literal); numeric references and known named references are left untouched."""
 import html.entities
 names=html.entities.html5
 def keep(m):
  rest=text[m.end():m.end()+40]
  if re.match(r'#([0-9]+|[xX][0-9a-fA-F]+);?',rest): return '&'
  word=re.match(r'[A-Za-z][A-Za-z0-9]*;?',rest)
  if word and any(word.group(0)[:i] in names for i in range(len(word.group(0)),1,-1)): return '&'
  return '&amp;'
 return re.sub(r'&',keep,text)

def css_errors(nodes):
 out=[]
 for n in nodes:
  if n.type=='error': out.append(n.message)
  for attr in ('prelude','content'):
   v=getattr(n,attr,None)
   if isinstance(v,list): out+=css_errors(v)
 return out

def sql_parse(text):
 """SQLite's own engine compiles the schema in a private in-memory database whose authorizer
 admits only schema statements (nothing touches a file or the network); otherwise sqlglot in
 strict mode for MySQL or PostgreSQL. Returns (parser, method) or None."""
 import sqlite3
 c=sqlite3.connect(':memory:')
 allowed={sqlite3.SQLITE_CREATE_TABLE,sqlite3.SQLITE_CREATE_INDEX,sqlite3.SQLITE_CREATE_TRIGGER,sqlite3.SQLITE_CREATE_VIEW,sqlite3.SQLITE_DROP_TABLE,sqlite3.SQLITE_DROP_INDEX,sqlite3.SQLITE_INSERT,sqlite3.SQLITE_READ,sqlite3.SQLITE_UPDATE,sqlite3.SQLITE_DELETE,sqlite3.SQLITE_SELECT,sqlite3.SQLITE_FUNCTION,sqlite3.SQLITE_TRANSACTION,sqlite3.SQLITE_ALTER_TABLE,sqlite3.SQLITE_REINDEX}
 c.set_authorizer(lambda action,*_: sqlite3.SQLITE_OK if action in allowed else sqlite3.SQLITE_DENY)
 try:
  c.executescript(text); return ('sqlite3 '+sqlite3.sqlite_version,'SQLITE_ENGINE_IN_MEMORY_SCHEMA_ONLY')
 except Exception: pass
 finally: c.close()
 try:
  import sqlglot
  from sqlglot.errors import ErrorLevel
 except Exception: return None
 for dialect in ('mysql','postgres'):
  try:
   # Unsupported syntax degrades to an opaque Command node: that is not a parse.
   trees=sqlglot.parse(text,read=dialect,error_level=ErrorLevel.RAISE)
   if trees and all(t is not None and not isinstance(t,sqlglot.exp.Command) and not t.find(sqlglot.exp.Command) for t in trees):
    return ('sqlglot '+sqlglot.__version__+' '+dialect,'SQLGLOT_STRICT_DIALECT_PARSER')
  except Exception: continue
 return None

def typescript_diagnostics(path, text):
 """Syntactic diagnostics of the TypeScript compiler locked in apps/web (no type checking, no
 emit). None when the compiler is unavailable."""
 ts=pathlib.Path(__file__).resolve().parents[2]/'apps/web/node_modules/typescript/lib/typescript.js'
 if not ts.is_file(): return None
 script=("const ts=require(process.argv[1]);let s='';process.stdin.on('data',d=>s+=d).on('end',()=>{"
         "const k={'.jsx':ts.ScriptKind.JSX,'.tsx':ts.ScriptKind.TSX}[require('path').extname(process.argv[2])]||ts.ScriptKind.TS;"
         "const f=ts.createSourceFile(process.argv[2],s,ts.ScriptTarget.Latest,false,k);"
         "console.log(JSON.stringify({version:ts.version,errors:f.parseDiagnostics.map(d=>ts.flattenDiagnosticMessageText(d.messageText,' ')+' @'+d.start)}))})")
 try: r=subprocess.run(['node','-e',script,str(ts),path],input=text.encode(),capture_output=True,timeout=60,check=True)
 except Exception: return None
 return json.loads(r.stdout)['errors']

def confirm_invalid(path, content, language):
 """When no admissible parser accepts a file, ask the language's reference parser whether the
 file itself is invalid. Returns (parser, first error) only when the reference parser rejects it;
 a confirmed-invalid file is a donor defect, not an unknown."""
 text=content.decode('utf-8','replace')
 try:
  if language=='python':
   import ast,platform
   try: ast.parse(text); return None
   except SyntaxError as e: return ('CPython '+platform.python_version()+' ast',f'{e.msg} at line {e.lineno}')
  if language=='html':
   import html5lib
   # A template partial is a fragment, not a document; and html5lib predates the WHATWG change
   # that made a bare "&" before whitespace valid, so its entity complaint never confirms.
   if TEMPLATE_TAG.search(text): return None  # template tags generate markup: never confirm from raw text
   document=re.match(r'\s*(<!--.*?-->\s*)*<(!doctype|html)\b',text,re.I|re.S)
   first=re.search(r'<([a-zA-Z][a-zA-Z0-9]*)',text)
   container={'tr':'tbody','td':'tr','th':'tr','li':'ul','option':'select','tbody':'table','thead':'table'}.get(first.group(1).lower() if first else '','div')
   try:
    parser=html5lib.HTMLParser(strict=True)
    parser.parse(text) if document else parser.parseFragment(text,container=container)
    return None
   except Exception as e:
    if 'entity' in str(e).lower(): return None
    return ('html5lib '+html5lib.__version__+' strict (WHATWG parsing algorithm, '+('document' if document else 'fragment')+')',str(e)[:200])
  if pathlib.Path(path).suffix in ('.jsx','.ts','.tsx','.mts','.cts'):
   d=typescript_diagnostics(path,text)
   if d: return ('typescript (apps/web lock)',d[0][:200])
 except Exception: return None
 return None

